@extends('layouts.app') @section('title','Pilih Laporan') @section('content')<div class="page-header"><div><h1>Pilih Laporan</h1><p class="muted">Laporan yang dapat Anda akses.</p></div>@if(auth()->user()->is_super_admin)<a class="btn btn-primary" href="{{ route('reports.create') }}">Buat Laporan</a>@endif</div>@if($reports->isEmpty())<div class="card empty"><h2>Belum ada Laporan</h2><p class="muted">Super Admin dapat membuat Laporan pertama.</p></div>@else<div class="grid metrics">@foreach($reports as $item)<a class="card" style="text-decoration:none;color:inherit;border-top:5px solid {{ $item->color }}" href="{{ route('reports.dashboard',$item) }}"><div class="actions"><span class="badge">{{ $item->status==='ACTIVE'?'Aktif':($item->status==='CLOSED'?'Ditutup':'Diarsipkan') }}</span><span class="badge">{{ auth()->user()->is_super_admin ? 'Super Admin' : ['ADMIN' => 'Admin Laporan', 'OFFICER' => 'Petugas', 'VIEWER' => 'Viewer'][$item->pivot->role] }}</span></div><h2>{{ $item->name }}</h2><p class="muted">{{ $item->description ?: 'Tanpa keterangan' }}</p><strong>Buka Laporan →</strong></a>@endforeach</div>@endif @endsection
